#include <LVRS/ViewModelRegistry.h>
#include <LVRS/StateModel.h>
#include <iiSDKCore/Core/Property/ObservableReadScope.h>
#include <iostream>
#include <thread>
using namespace ii;
namespace {
using V=core::Value;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> value){if(!value){if(value.error().cause)std::rethrow_exception(value.error().cause);throw std::runtime_error(value.error().message);}return std::move(*value);}
void good(core::Result<void> value){if(!value)throw std::runtime_error(value.error().message);}
template<class F>auto port(F action){return std::make_shared<lvrs::ViewModelRegistryPort>(std::move(action));}
void defaults(){lvrs::ViewModelRegistry registry;check(registry.keys().empty()&&registry.views().empty()&&registry.bindings().empty()&&registry.owners().empty()&&registry.descriptors().empty()&&registry.last_error().empty(),"Registry defaults differ");check(!registry.get("missing")&&!registry.read_property("missing","busy"),"Missing registry lookup returned data");}
void registration(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::StateModel>();take(registry.set("  Main  ",model));check(registry.keys()==std::vector<std::string>{"Main"}&&registry.get("Main")==model&&model->key()=="Main","Registry normalization or initial model key differs");check(!take(registry.set("Main",model)),"Same registry entry was changed");take(registry.register_view_model(model," Alias "));check(model->key()=="Alias"&&registry.get("Alias")==model&&registry.get("Main")==model,"Fallback registration lost model aliases");}
void borrowing(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.set("B",model));take(registry.bind_view("writer","A",true));model.reset();check(registry.keys().empty()&&registry.views().empty()&&registry.owners().empty(),"A destroyed borrowed model left aliases, views or ownership behind");}
void retention(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();std::weak_ptr<lvrs::ViewModel> weak=model;take(registry.set("A",model,lvrs::ModelRetention::retain));take(registry.set("B",model));model.reset();check(!weak.expired(),"An explicitly retained model was not owned");take(registry.remove("A"));check(!weak.expired()&&registry.get("B"),"Removing one alias destroyed a shared retained model");take(registry.remove("B"));check(weak.expired(),"Last alias removal leaked a retained model");}
void permissions(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("Main",model));take(registry.bind_view("Reader","Main"));take(registry.claim_ownership("Writer","Main"));check(registry.can_write("Writer")&&!registry.can_write("Reader")&&registry.owner_of("Main")=="Writer","Single-writer ownership differs");check(!take(registry.claim_ownership("Other","Main"))&&registry.last_error()=="ViewModel is already owned by another view","Conflicting ownership was granted");check(!take(registry.update_property("Reader","busy",V(true)))&&model->busy()==false,"Reader changed a model");check(take(registry.update_property("Writer","busy",V(true)))&&model->busy(),"Owner could not change the live model");check(take(registry.update_property("Writer","busy",V(true))),"An accepted unchanged property write was reported as failure");take(registry.bind_view("Writer","Main",false));check(!registry.can_write("Writer")&&registry.owner_of("Main").empty(),"Read-only rebinding did not relinquish ownership");}
void switching(){lvrs::ViewModelRegistry registry;auto a=std::make_shared<lvrs::ViewModel>(),b=std::make_shared<lvrs::ViewModel>();take(registry.set("A",a));take(registry.set("B",b));take(registry.bind_view("Editor","A",true));take(registry.bind_view("Editor","B",true));check(registry.owner_of("A").empty()&&registry.owner_of("B")=="Editor"&&registry.key_for_view("Editor")=="B","Switching a view retained its previous ownership");take(registry.release_ownership("Editor"));check(registry.key_for_view("Editor")=="B"&&!registry.can_write("Editor"),"Release removed a read binding");take(registry.unbind_view("Editor"));check(!registry.get_for_view("Editor")&&registry.views().empty(),"Unbind retained a view");}
void properties(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::StateModel>();take(registry.set("Main",model));take(registry.bind_view("Editor","Main",true));check(take(registry.update_property("Editor","values",V(V::Object{{"nullable",V{}}})))&&model->has_value("nullable"),"State values were not written through their native setter");check(registry.read_property("Editor","values")==V(V::Object{{"nullable",V{}}}),"Registry read did not return owned live state");check(!take(registry.update_property("Editor","revision",V(9))),"Read-only model property was changed");auto invalid=registry.update_property("Editor","busy",V("wrong"));check(!invalid&&!model->busy(),"Invalid property type changed the model");check(!registry.read_property("Editor","unknown"),"Missing property was confused with explicit null");}
void descriptors(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::StateModel>();take(registry.set("Main",model));take(registry.bind_view("Editor","Main",true));take(model->set_display_name("Inspector"));take(model->set_value("count",V(3)));auto d=registry.descriptor("Main");check(d.at("key")==V("Main")&&d.at("viewModelKey")==V("Main")&&d.at("className")==V("StateModel")&&d.at("owner")==V("Editor")&&d.at("views")==V(V::Array{V("Editor")})&&d.at("displayName")==V("Inspector")&&d.at("stateModel")==V(true)&&d.at("values")==V(V::Object{{"count",V(3)}}),"Registry descriptor omitted live model, owner or view data");}
void replacement(){lvrs::ViewModelRegistry registry;auto a=std::make_shared<lvrs::ViewModel>(),b=std::make_shared<lvrs::ViewModel>();take(registry.set("Main",a));take(registry.bind_view("Editor","Main",true));take(registry.set("Main",b));check(registry.get_for_view("Editor")==b&&registry.can_write("Editor"),"Model replacement discarded its existing binding");int changes=0;auto receiver=port([&](const auto& e){if(e.event==lvrs::ViewModelRegistryEvent::descriptors)++changes;});good(registry.observe(receiver));take(a->set_busy(true));check(changes==0,"Replaced model still invalidated the registry");take(b->set_busy(true));check(changes==1,"Replacement model did not invalidate its descriptor");}
void observation(){lvrs::ViewModelRegistry registry;auto a=std::make_shared<lvrs::ViewModel>(),b=std::make_shared<lvrs::ViewModel>();take(registry.set("A",a));take(registry.set("B",b));std::vector<core::ObservableRead> reads;core::ObservableReadScope::collect([&](auto value){reads.push_back(std::move(value));},[&]{return registry.descriptor("A");});int changes=0;std::vector<core::ObservableSubscription> watches;for(auto& read:reads)watches.push_back(read.subscribe([&]{++changes;}));take(b->set_busy(true));check(changes==0,"A different model widened descriptor dependencies");take(a->set_busy(true));check(changes==1,"One model change did not invalidate its descriptor exactly once");}
void errors(){lvrs::ViewModelRegistry registry;check(!take(registry.bind_view(" ","Main"))&&registry.last_error()=="Empty view id","Empty view error differs");check(!take(registry.bind_view("View","Main"))&&registry.last_error()=="ViewModel key is not registered","Unknown model error differs");check(!take(registry.bind_route_view_model("/empty",{},{}))&&registry.last_error()=="ViewModel key is not registered","Missing route model unexpectedly cleared the previous error");take(registry.clear());check(registry.last_error()=="ViewModel key is not registered","Clear changed error state");}
void route(){lvrs::ViewModelRegistry registry;auto a=std::make_shared<lvrs::ViewModel>(),b=std::make_shared<lvrs::ViewModel>();take(registry.set("A",a));take(registry.set("B",b));take(registry.bind_route_view_model("/route",{{"viewModelKey",V("A")},{"viewId",V("Route")},{"writable",V(false)}},{{"modelKey",V("B")},{"viewId",V("Params")},{"writable",V(true)}}));check(registry.key_for_view("Route")=="A"&&!registry.can_write("Route")&&!registry.get_for_view("Params"),"Route model metadata precedence differs");take(registry.bind_route_view_model("",{},{{"modelKey",V("B")}},-2));check(registry.key_for_view("_component_0")=="B","Component fallback view id differs");}
void notification(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();std::vector<lvrs::ViewModelRegistryEvent> events;auto receiver=port([&](const auto& change){events.push_back(change.event);check(registry.get("A")==model,"An observer saw uncommitted registry entries");});good(registry.observe(receiver));take(registry.set("A",model));check(events==std::vector{lvrs::ViewModelRegistryEvent::keys,lvrs::ViewModelRegistryEvent::descriptors},"Registry registration notification order differs");}
void failure(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();int calls=0;auto bad=port([](const auto&){throw std::runtime_error("registry observer");});auto next=port([&](const auto&){++calls;});good(registry.observe(bad));good(registry.observe(next));auto result=registry.set("A",model);check(!result&&registry.get("A")==model&&calls==2,"Observer failure rolled back registry state or stopped fanout");}
void reentrant(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();bool blocked=false;auto receiver=port([&](const auto&){auto nested=registry.remove("A");blocked=!nested&&nested.error().code==core::ErrorCode::busy;});good(registry.observe(receiver));take(registry.set("A",model));check(blocked&&registry.get("A"),"Registry allowed reentrant mutation");}
void ownership(){lvrs::ViewModelRegistry registry;bool blocked=false;std::thread worker([&]{auto result=registry.clear();blocked=!result&&result.error().code==core::ErrorCode::wrong_executor;try{(void)registry.keys();blocked=false;}catch(const std::logic_error&) {}});worker.join();check(blocked,"Registry allowed foreign-thread access");}
void nonmutation(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::StateModel>();take(registry.set("A",model));int changes=0;auto receiver=port([&](const auto&){++changes;});good(registry.observe(receiver));for(int n=0;n<100;++n){(void)registry.keys();(void)registry.descriptors();(void)registry.get("A");}check(changes==0&&model->revision()==0&&!model->busy(),"Registry inspection mutated model or view state");}
class Record final:public lvrs::ModelProperties {
    V stored;
    DescriptorSignal changed=descriptor_signal();
public:
    mutable int descriptions=0;
    std::optional<V> read_property(std::string_view key)const override{return key=="nullable"?std::optional<V>(stored):std::nullopt;}
    core::Result<bool> write_property(std::string_view key,V value)override{if(key!="nullable")return false;if(stored==value)return true;stored=std::move(value);auto result=changed.notify();if(!result)return std::unexpected(result.error());return true;}
    V::Object model_descriptor()const override{++descriptions;return {{"className",V("Record")}};}
};
void generic(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<Record>();take(registry.set("Raw",model));take(registry.bind_view("Editor","Raw",true));check(model->descriptions==0,"Registration or binding cloned an entire model descriptor");check(registry.read_property("Editor","nullable")==V{}&&!registry.read_property("Editor","missing"),"Generic native properties lost null/presence");take(registry.update_property("Editor","nullable",V("Live")));check(registry.read_property("Editor","nullable")==V("Live")&&model->descriptions==0,"A property operation fetched the whole model");check(registry.descriptor("Raw").at("viewModel")==V(false)&&model->descriptions==1,"Generic endpoint required a ViewModel concrete class");}
void limits(){lvrs::ViewModelRegistry registry({.models=1,.views=1,.token_bytes=8});auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));check(!registry.set("B",model)&&registry.keys()==std::vector<std::string>{"A"},"A failed capacity admission changed model indices");take(registry.bind_view("View","A"));check(!registry.bind_view("Other","A")&&registry.views()==std::vector<std::string>{"View"},"A failed view admission changed bindings");check(!registry.set("TooLongKey",model)&&registry.keys().size()==1,"An oversized token changed the registry");}
void pending_source(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();bool changed=false;int descriptors=0;auto receiver=port([&](const auto& event){if(event.event==lvrs::ViewModelRegistryEvent::keys&&!changed){changed=true;take(model->set_busy(true));}if(event.event==lvrs::ViewModelRegistryEvent::descriptors)++descriptors;});good(registry.observe(receiver));take(registry.set("A",model));check(changed&&model->busy()&&descriptors==2&&registry.descriptor("A").at("busy")==V(true),"A model change during registry notification was lost");}
void alias_permissions(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.set("B",model));take(registry.bind_view("First","A",true));take(registry.bind_view("Second","B",true));check(registry.can_write("First","A")&&registry.can_write("Second","B")&&!registry.can_write("First","B"),"Ownership no longer belongs to each registered key");take(registry.set("A",{}));check(!registry.get_for_view("First")&&!registry.can_write("First")&&registry.can_write("Second"),"Null replacement left stale views or damaged another alias");}
void registry_lifetime(){auto registry=std::make_shared<lvrs::ViewModelRegistry>();auto* raw=registry.get();std::weak_ptr<lvrs::ViewModelRegistry> weak=registry;auto model=std::make_shared<lvrs::ViewModel>();auto receiver=port([&](const auto&){registry.reset();});good(registry->observe(receiver));take(raw->set("A",model));check(weak.expired(),"An in-flight registry command leaked its retired owner");}

void retire_prepare(){auto registry=std::make_shared<lvrs::ViewModelRegistry>();auto* raw=registry.get();auto model=std::make_shared<lvrs::ViewModel>();auto receiver=std::make_shared<lvrs::ViewModelChangePort>([&](const auto&){registry.reset();});good(model->observe(receiver));auto result=raw->set("A",model);check(!result&&result.error().code==core::ErrorCode::closed,"A registry retired during model-key preparation accepted new work");}

class KeyDenied final:public lvrs::ModelProperties {public:bool is_view_model()const noexcept override{return true;}std::optional<V> read_property(std::string_view key)const override{return key=="key"?std::optional<V>(V("")):std::nullopt;}core::Result<bool> write_property(std::string_view,V)override{return false;}V::Object model_descriptor()const override{return {{"viewModel",V(true)}};}};
void rejected_key(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<KeyDenied>();check(!take(registry.set("Denied",model))&&registry.keys().empty()&&registry.last_error()=="Failed to update model property","A rejected automatic model key was registered as success");}

void retirement(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.bind_view("Editor","A",true));take(registry.bind_view("External","A"));take(registry.bind_view("Invalid","Missing"));const auto error=registry.last_error();const std::vector<std::string> ids{"Editor","Editor","Unknown"};check(take(registry.retire_views(ids))&&registry.views()==std::vector<std::string>{"External"}&&registry.owners().empty()&&registry.last_error()==error,"Lifecycle cleanup lost duplicate safety, other bindings or lastError");check(!take(registry.retire_views(ids)),"Repeated cleanup was not inert");}
void pending_retirement(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.bind_view("Editor","A",true));bool requested=false;auto receiver=port([&](const auto&){if(requested)return;requested=true;const std::vector<std::string> ids{"Editor"};check(take(registry.retire_views(ids)),"An observer could not request lifecycle cleanup");auto nested=registry.bind_view("Other","A");check(!nested&&nested.error().code==core::ErrorCode::busy&&registry.get_for_view("Editor"),"Cleanup mutated reentrantly or admitted an ordinary nested write");});good(registry.observe(receiver));take(registry.update_property("Editor","busy",V(true)));check(requested&&model->busy()&&registry.views().empty()&&registry.owners().empty(),"Deferred retirement was lost after the model command");}
void retire_failure(){lvrs::ViewModelRegistry registry;auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.bind_view("First","A",true));take(registry.bind_view("Second","A"));int delivered=0;auto bad=port([](const auto&){throw std::runtime_error("retirement observer");});auto next=port([&](const auto&){++delivered;});good(registry.observe(bad));good(registry.observe(next));const std::vector<std::string> ids{"First","Second"};auto result=registry.retire_views(ids);check(!result&&result.error().cause&&registry.views().empty()&&registry.owners().empty()&&delivered>=4,"An observation error interrupted cleanup or fanout");}
void retire_limits(){lvrs::ViewModelRegistry registry({.views=1,.token_bytes=4});auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.bind_view("View","A"));const std::vector<std::string> unknown{"None","Lost","Gone"};check(!take(registry.retire_views(unknown))&&registry.get_for_view("View"),"Cleanup of unbound IDs incorrectly used registered view capacity");const std::vector<std::string> invalid{"View","oversized"};check(!registry.retire_views(invalid)&&registry.get_for_view("View"),"Invalid retirement admission partially removed existing bindings");bool blocked=false;std::thread worker([&]{auto result=registry.retire_views(unknown);blocked=!result&&result.error().code==core::ErrorCode::wrong_executor;});worker.join();check(blocked,"Retirement accepted a foreign thread");}
void route_identity(){const auto binding=lvrs::ViewModelRegistry::route_binding("/path",{{"viewId",V(42)},{"writable",V(false)}},{{"viewId",V("Ignored")},{"modelKey",V("A")},{"writable",V(true)}});check(binding.view_id=="42"&&binding.model_key=="A"&&!binding.writable,"Shared route resolution lost source scalar or metadata precedence");const auto empty=lvrs::ViewModelRegistry::route_binding("",{},{},3);check(empty.view_id=="_component_3"&&empty.model_key.empty(),"Tracking cannot resolve an identity without a model key");}
void admission(){lvrs::ViewModelRegistry registry({.token_bytes=4});auto model=std::make_shared<lvrs::ViewModel>();take(registry.set("A",model));take(registry.bind_view("View","Lost"));const auto error=registry.last_error();good(registry.validate_view_admission(" View "));check(!registry.validate_view_admission("oversized")&&!registry.validate_view_admission("  ")&&registry.last_error()==error&&registry.views().empty(),"View preflight changed registry state or accepted an invalid identity");bool blocked=false;std::thread worker([&]{auto result=registry.validate_view_admission("View");blocked=!result&&result.error().code==core::ErrorCode::wrong_executor;});worker.join();check(blocked,"View preflight ignored its command domain");}

}
int main(int argc,char** argv){try{std::string name=argc>1?argv[1]:"defaults";if(name=="defaults")defaults();else if(name=="registration")registration();else if(name=="borrowing")borrowing();else if(name=="retention")retention();else if(name=="permissions")permissions();else if(name=="switching")switching();else if(name=="properties")properties();else if(name=="descriptors")descriptors();else if(name=="replacement")replacement();else if(name=="observation")observation();else if(name=="errors")errors();else if(name=="route")route();else if(name=="notification")notification();else if(name=="failure")failure();else if(name=="reentrant")reentrant();else if(name=="ownership")ownership();else if(name=="nonmutation")nonmutation();else if(name=="generic")generic();else if(name=="limits")limits();else if(name=="pending_source")pending_source();else if(name=="alias_permissions")alias_permissions();else if(name=="registry_lifetime")registry_lifetime();else if(name=="retire_prepare")retire_prepare();else if(name=="rejected_key")rejected_key();else if(name=="retirement")retirement();else if(name=="pending_retirement")pending_retirement();else if(name=="retire_failure")retire_failure();else if(name=="retire_limits")retire_limits();else if(name=="route_identity")route_identity();else if(name=="admission")admission();else throw std::runtime_error("Unknown registry case");std::cout<<"Native registry "<<name<<" passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
